    <h2 id="docs-search-title">Search documentation</h2>
    <button type="button" onclick={() => dialog.close()} aria-label="Close search">Close</button>
  </div>
  <label for="docs-search-query">Search terms</label>
  <input id="docs-search-query" bind:this={input} bind:value={query} oninput={search} type="search" autocomplete="off" placeholder="Search documentation…" />
  <p role="status">{pending ? "Searching…" : query.trim() && !failure ? `${results.length} results` : "Enter a term to search."}</p>
  {#if failure}<p role="alert">{failure}</p>{/if}
  <ul>
    {#each results as result (result.id)}
      <li><a href={result.url} onclick={() => dialog.close()}>{result.title}</a></li>
    {/each}
  </ul>
</dialog>

